files.content:
html {
  block-size: 100%;
}

body {
  position: relative;
  display: flex;
  justify-content: center;
  align-items: center;
  margin: 0;
  font-family: 'Open Sans', sans-serif;
  block-size: 100%;
}

.image {
  border-radius: 50%;
  inline-size: 195px;
  block-size: 190px;
  box-shadow: 0 0 3px 4px #1919ff, 0 0 0 8px #6fc1fd, 0 0 0 12px #dfe9f5, 0 0 0 16px #6fc1fd, 0 0 3px 20px #1919ff;
}
